{"command": "cd /tmp/t && python3 - <<'PYEOF' > tree3.txt
import re
s=open('test.html').read()
start = s.index("id='bytes'>")+len("id='bytes'>")
end = s.index("\n    <div id='ascii'>")
body=s[start:end]
pat=re.compile(r"<(/?)span([^>]*)>")
i=0
events=[]
while True:
    m=pat.search(body,i)
    if not m:
        events.append(("TEXT",None,body[i:],None,None)); break
    if m.start()>i:
        txt=body[i:m.start()]
        events.append(("TEXT",None,txt,None,None))
    if m.group(1)=='':
        events.append(("OPEN",None,None,m.group(2).strip(),None))
    else:
        events.append(("CLOSE",None,None,None,None))
    i=m.end()
# compute offsets
off=0
res=[]
openstack=[]
for k,ev in enumerate(events):
    if ev[0]=="TEXT":
        toks=re.findall(r"&nbsp;(.)|(?<![0-9a-f])([0-9a-f]{2})(?![0-9a-f])", ev[2])
        n=len(toks)
        res.append(["TEXT",off,n,ev[2]])
        off+=n
    elif ev[0]=="OPEN":
        res.append(["OPEN",off,ev[3],None])
        openstack.append(off)
    else:
        st=openstack.pop()
        res.append(["CLOSE",off,st,None])
def fmt(t): return t.replace('\n','\\n')
# print with indent
depth=0
for r in res:
    if r[0]=="CLOSE":
        depth-=1
    else:
        if r[0]=="OPEN":
            print("%sOPEN %d..%s %s" % ("  "*depth, r[1], r[1], r[2]))
            depth+=1
        else:
            print("%sTEXT %d len=%d %r" % ("  "*depth, r[1], r[2], fmt(r[3])))
PYEOF
