{"command": "cd /tmp/w && cat > probe.py <<'PYEOF'
import struct, subprocess, os, re, sys
BASE=b'\x7fELF\x02\x01\x01\x00'+b'\0'*8
BIN='/workspace/executable'
def mk_hdr(etype=2,machine=0x3e,abi=0,cls=2,data=1,shnum=0,phnum=0,shoff=0,phoff=0,extra=b'',entry=0,flags=0,shstrndx=0,phentsize=56,shentsize=64,ehsize=64,ver=1):
    ident=bytearray(BASE)
    ident[4]=cls; ident[5]=data; ident[7]=abi; ident[6]=ver
    b=bytearray(ident)+bytearray(b'\0'*48)
    struct.pack_into('<HHI',b,16,etype,machine,ver)
    struct.pack_into('<QQQI',b,24,entry,phoff,shoff,flags)
    struct.pack_into('<HHHHHH',b,52,ehsize,phentsize,phnum,shentsize,shnum,shstrndx)
    b+=extra
    return bytes(b)
def run_bytes(data,name='p'):
    open(name,'wb').write(data)
    r=subprocess.run([BIN,name],capture_output=True)
    if r.returncode!=0:
        return None, r.stderr.decode('utf8','replace')
    return open(name+'.html').read(), None
def run(name):
    r=subprocess.run([BIN,name],capture_output=True)
    if r.returncode!=0:
        return None, r.stderr.decode('utf8','replace')
    return open(name+'.html').read(), None
def fileinfo_of(s):
    i=s.index("<table>\n"); j=s.index("    </table>",i)
    return re.findall(r'<td>(.*?)</td>', s[i:j])[1::2]
def show(vals, labels=None, prefix='p'):
    for k,v in vals.items():
        data=mk_hdr(**v)
        s,err=run_bytes(data,prefix)
        if err:
            print(k, "ERR", ' | '.join(err.strip().split('\n')[1:3]))
        else:
            print(k, fileinfo_of(s))
