import struct, subprocess, re, mk64
BIN='/workspace/executable'
names=b'\0.shstrtab\0'
def build(nsecs, types=None, datas=None):
    # sections: NULL, then (nsecs-2) PROGBITS 16 bytes, then shstrtab
    secs=[(0,0,0,0,None,0,0,1,0)]
    for i in range(nsecs-2):
        secs.append((0,1,6,0x400+i*16,b'\x90'*16,0,0,16,0))
    secs.append((0,3,0,0,bytes(names),0,0,1,0))
    d=mk64.mk64(names,secs,shstrndx=nsecs-1,e_type=2)
    shoff=struct.unpack_from('<Q',d,40)[0]
    b=bytearray(d)
    if types:
        for k,t in enumerate(types):
            struct.pack_into('<I',b,shoff+k*64+4,t)
    if datas:
        for k,(off,val) in enumerate(datas):
            struct.pack_into('<I',b,shoff+k*64+off,val)
    return bytes(b)
def run(data):
    open('p3','wb').write(data)
    r=subprocess.run([BIN,'p3'],capture_output=True)
    if r.returncode: return None, r.stderr.decode()
    return open('p3.html').read(), None
def shdr_info(data):
    s,err=run(data)
    if err: return None, err
    res={}
    for m in re.finditer(r"<table class='conceal itable' id='(info_shdr\d+)'>\n(.*?)</table>", s, re.S):
        vals=re.findall(r'<td>(.*?)</td>', m.group(2))
        res[m.group(1)]=vals[1::2]
    return res, None
def shdr_bytes_types(types):
    return build(len(types), types=types)
