// ELF structures and parsing helpers.
//
// Only the fields that the report generator needs are modelled here.  Both
// 32-bit and 64-bit files, little- and big-endian, are supported.

#[derive(Clone, Copy, Default)]
pub struct Phdr {
    pub p_type: u32,
    pub p_flags: u32,
    pub p_offset: u64,
    pub p_vaddr: u64,
    pub p_paddr: u64,
    pub p_filesz: u64,
    pub p_memsz: u64,
    pub p_align: u64,
}

#[derive(Clone, Copy, Default)]
pub struct Shdr {
    pub sh_name: u32,
    pub sh_type: u32,
    pub sh_flags: u64,
    pub sh_addr: u64,
    pub sh_offset: u64,
    pub sh_size: u64,
    pub sh_link: u32,
    pub sh_info: u32,
    pub sh_addralign: u64,
    pub sh_entsize: u64,
}

#[derive(Default)]
pub struct Elf {
    pub abi: u8,
    pub is64: bool,
    pub le: bool,
    pub e_type: u16,
    pub e_machine: u16,
    pub e_version: u32,
    pub e_entry: u64,
    pub e_phoff: u64,
    pub e_shoff: u64,
    pub e_flags: u64,
    pub e_ehsize: u16,
    pub e_phentsize: u16,
    pub e_phnum: u16,
    pub e_shentsize: u16,
    pub e_shnum: u16,
    pub e_shstrndx: u16,
    pub phdrs: Vec<Phdr>,
    pub shdrs: Vec<Shdr>,
}

pub const PT_NULL: u32 = 0;
pub const PT_LOAD: u32 = 1;
pub const PT_DYNAMIC: u32 = 2;
pub const PT_INTERP: u32 = 3;
pub const PT_NOTE: u32 = 4;
pub const PT_GNU_EH_FRAME: u32 = 0x6474_e550;
pub const PT_GNU_STACK: u32 = 0x6474_e551;
pub const PT_GNU_RELRO: u32 = 0x6474_e552;
pub const PT_LO_OS: u32 = 0x6000_0000;
pub const PT_HI_OS: u32 = 0x6fff_ffff;
pub const PT_LO_PROC: u32 = 0x7000_0000;
pub const PT_HI_PROC: u32 = 0x7fff_ffff;

pub const SHT_NOBITS: u32 = 8;
pub const SHT_STRTAB: u32 = 3;

/// Program header type names, mirroring the names used by the report.
pub fn ptype_name(v: u32) -> String {
    match v {
        0 => "NULL".into(),
        1 => "LOAD".into(),
        2 => "DYNAMIC".into(),
        3 => "INTERP".into(),
        4 => "NOTE".into(),
        5 => "SHLIB".into(),
        6 => "PHDR".into(),
        7 => "TLS".into(),
        PT_GNU_EH_FRAME => "GNU_EH_FRAME (OS-specific)".into(),
        PT_GNU_STACK => "GNU_STACK (OS-specific)".into(),
        PT_GNU_RELRO => "GNU_RELRO (OS-specific)".into(),
        PT_LO_OS => "LOOS".into(),
        PT_HI_OS => "HIOS".into(),
        PT_LO_PROC => "LOPROC".into(),
        PT_HI_PROC => "HIPROC".into(),
        other => format!("Unknown: {}", other),
    }
}

/// Section header type names.
pub fn shtype_name(v: u32) -> String {
    match v {
        0 => "NULL".into(),
        1 => "PROGBITS".into(),
        2 => "SYMTAB".into(),
        3 => "STRTAB".into(),
        4 => "RELA".into(),
        5 => "HASH".into(),
        6 => "DYNAMIC".into(),
        7 => "NOTE".into(),
        SHT_NOBITS => "NOBITS".into(),
        9 => "REL".into(),
        10 => "SHLIB".into(),
        11 => "DYNSYM".into(),
        14 => "INIT_ARRAY".into(),
        15 => "FINI_ARRAY".into(),
        0x6fff_fff6 => "GNU_HASH (OS-specific)".into(),
        0x6fff_fffe => "VER_NEED (OS-specific)".into(),
        0x6000_0000 => "LOOS".into(),
        0x6fff_ffff => "HIOS".into(),
        0x7000_0000 => "LOPROC".into(),
        0x7fff_ffff => "HIPROC".into(),
        other => format!("Unknown: {}", other),
    }
}

/// Object type names (e_type).
pub fn objtype_name(v: u16) -> String {
    match v {
        0 => "None (NONE)".into(),
        1 => "Relocatable object file (REL)".into(),
        2 => "Executable file (EXEC)".into(),
        3 => "Shared object file (DYN)".into(),
        4 => "Core file (CORE)".into(),
        0xfe00..=0xfeff => "Environment-specific use".into(),
        0xff00..=0xffff => "Processor-specific use".into(),
        other => format!("Unknown {}", other),
    }
}

/// Machine names (e_machine).
pub fn machine_name(v: u16) -> String {
    match v {
        0 => "None".into(),
        1 => "AT&T WE 32100".into(),
        2 => "SPARC".into(),
        3 => "x86".into(),
        4 => "Motorolla 68000".into(),
        5 => "Motorolla 88000".into(),
        6 => "Intel MCU".into(),
        7 => "Intel 80860".into(),
        8 => "MIPS".into(),
        9 => "IBM System/370".into(),
        10 => "MIPS RS3000 little-endian".into(),
        14 => "HP PA-RISC".into(),
        19 => "Intel 80960".into(),
        20 => "PowerPC".into(),
        21 => "PowerPC 64-bit".into(),
        22 => "S390".into(),
        40 => "ARM Aarch32".into(),
        50 => "Itanium IA-64".into(),
        62 => "x86-64".into(),
        183 => "ARM Aarch64".into(),
        190 => "CUDA".into(),
        224 => "AMDGPU".into(),
        243 => "RISC-V".into(),
        other => format!("Unknown: {}", other),
    }
}

/// OS/ABI names (EI_OSABI).
