        0x6fff_fff6 => "GNU_HASH (OS-specific)".into(),
        0x6fff_fffe => "VER_NEED (OS-specific)".into(),
        0x6000_0000 => "LOOS".into(),
        0x6fff_ffff => "HIOS".into(),
        0x7000_0000 => "LOPROC".into(),
        0x7fff_ffff => "HIPROC".into(),
        other => format!("Unknown: {}", other),
    }
}

/// Object type names (e_type).
pub fn objtype_name(v: u16) -> String {
    match v {
        0 => "None (NONE)".into(),
        1 => "Relocatable object file (REL)".into(),
        2 => "Executable file (EXEC)".into(),
        3 => "Shared object file (DYN)".into(),
        4 => "Core file (CORE)".into(),
        0xfe00..=0xfeff => "Environment-specific use".into(),
        0xff00..=0xffff => "Processor-specific use".into(),
        other => format!("Unknown {}", other),
    }
}

/// Machine names (e_machine).
pub fn machine_name(v: u16) -> String {
    match v {
        0 => "None".into(),
        1 => "AT&T WE 32100".into(),
        2 => "SPARC".into(),
        3 => "x86".into(),
        4 => "Motorolla 68000".into(),
        5 => "Motorolla 88000".into(),
        6 => "Intel MCU".into(),
        7 => "Intel 80860".into(),
        8 => "MIPS".into(),
        9 => "IBM System/370".into(),
        10 => "MIPS RS3000 little-endian".into(),
        14 => "HP PA-RISC".into(),
        19 => "Intel 80960".into(),
        20 => "PowerPC".into(),
        21 => "PowerPC 64-bit".into(),
        22 => "S390".into(),
        40 => "ARM Aarch32".into(),
        50 => "Itanium IA-64".into(),
        62 => "x86-64".into(),
        183 => "ARM Aarch64".into(),
        190 => "CUDA".into(),
        224 => "AMDGPU".into(),
        243 => "RISC-V".into(),
        other => format!("Unknown: {}", other),
    }
}

/// OS/ABI names (EI_OSABI).
pub fn abi_name(v: u8) -> String {
    match v {
        0 => "SysV".into(),
        1 => "HP-UX".into(),
        2 => "NetBSD".into(),
        3 => "Linux".into(),
        4 => "Hurd".into(),
        6 => "Solaris".into(),
        7 => "AIX".into(),
        8 => "IRIX".into(),
        9 => "FreeBSD".into(),
        10 => "Tru64".into(),
        11 => "Modesto".into(),
        12 => "OpenBSD".into(),
        13 => "OpenVMS".into(),
        255 => "Standalone".into(),
        other => format!("Unknown: {}", other),
    }
}

/// Segment permission flags: R W X
pub fn seg_flags_str(v: u32) -> String {
    let mut s = String::new();
    if v & 0x4 != 0 {
        s.push('R');
    }
    if v & 0x2 != 0 {
        s.push('W');
    }
    if v & 0x1 != 0 {
        s.push('X');
    }
    s
}

/// Section flags: W A X, or "0" when none.
pub fn sec_flags_str(v: u64) -> String {
    let mut s = String::new();
    if v & 0x1 != 0 {
        s.push('W');
    }
    if v & 0x2 != 0 {
        s.push('A');
    }
    if v & 0x4 != 0 {
        s.push('X');
    }
    if s.is_empty() {
        "0".to_string()
    } else {
        s
    }
}

fn rd_u16(d: &[u8], off: usize, le: bool) -> u16 {
    let b = [d[off], d[off + 1]];
    if le {
        u16::from_le_bytes(b)
    } else {
        u16::from_be_bytes(b)
    }
}

fn rd_u32(d: &[u8], off: usize, le: bool) -> u32 {
    let b = [d[off], d[off + 1], d[off + 2], d[off + 3]];
    if le {
        u32::from_le_bytes(b)
    } else {
        u32::from_be_bytes(b)
    }
}

fn rd_u64(d: &[u8], off: usize, le: bool) -> u64 {
    let mut b = [0u8; 8];
    b.copy_from_slice(&d[off..off + 8]);
    if le {
        u64::from_le_bytes(b)
    } else {
        u64::from_be_bytes(b)
    }
}

fn rd_addr(d: &[u8], off: usize, is64: bool, le: bool) -> u64 {
    if is64 {
        rd_u64(d, off, le)
    } else {
        rd_u32(d, off, le) as u64
    }
}

pub fn parse(data: &[u8]) -> Result<Elf, String> {
    if data.len() < 16 {
        return Err("file is smaller than ELF header's e_ident".to_string());
    }
    if &data[0..4] != b"\x7fELF" {
        return Err("mismatched magic: not an ELF file".to_string());
    }
    let class = data[4];
    let is64 = match class {
        1 => false,
        2 => true,
        other => return Err(format!("Unknown bitness: {}", other)),
    };
    let enc = data[5];
    let le = match enc {
        1 => true,
        2 => false,
        other => return Err(format!("Unknown endianness: {}", other)),
    };
    let ehdr_len = if is64 { 64 } else { 52 };
    if data.len() < ehdr_len {
        return Err("file is smaller than ELF file header".to_string());
    }

    if data[6] == 0 {
        // Matches the reference implementation, which indexes one byte before
        // the header size and therefore panics for e_ehsize == 0.
        crate::panic_index(len_of(data), usize::MAX, if is64 { "src/elf/parser.rs:117:18" } else { "src/elf/parser.rs:116:18" });
    }

    let mut e = Elf {
        abi: data[7],
        is64,
        le,
        e_type: rd_u16(data, 16, le),
        e_machine: rd_u16(data, 18, le),
        e_version: rd_u32(data, 20, le),
        e_entry: rd_addr(data, 24, is64, le),
        e_phoff: rd_addr(data, if is64 { 32 } else { 28 }, is64, le),
        e_shoff: rd_addr(data, if is64 { 40 } else { 32 }, is64, le),
        e_flags: rd_u32(data, if is64 { 48 } else { 36 }, le) as u64,
        e_ehsize: rd_u16(data, if is64 { 52 } else { 40 }, le),
        e_phentsize: rd_u16(data, if is64 { 54 } else { 42 }, le),
        e_phnum: rd_u16(data, if is64 { 56 } else { 44 }, le),
        e_shentsize: rd_u16(data, if is64 { 58 } else { 46 }, le),
        e_shnum: rd_u16(data, if is64 { 60 } else { 48 }, le),
        e_shstrndx: rd_u16(data, if is64 { 62 } else { 50 }, le),
        ..Default::default()
    };

    // Program headers
    let phnum = e.e_phnum as usize;
    let phentsize = e.e_phentsize as usize;
    if phnum > 0 {
        let end = e.e_phoff as usize + phnum * phentsize;
        if end > data.len() {
            crate::panic_range(end, data.len(), "src/elf/elfxx.rs:174:46");
        }
        let _ = data[e.e_phoff as usize..end];
        for i in 0..phnum {
            let b = e.e_phoff as usize + i * phentsize;
            e.phdrs.push(Phdr {
                p_type: rd_u32(data, b, le),
                p_flags: rd_u32(data, b + 4, le),
                p_offset: rd_addr(data, b + 8, is64, le),
                p_vaddr: rd_addr(data, b + 12, is64, le),
                p_paddr: rd_addr(data, b + 16, is64, le),
                p_filesz: rd_addr(data, b + 20, is64, le),
                p_memsz: rd_addr(data, b + 24, is64, le),
                p_align: rd_addr(data, b + 28, is64, le),
            });
        }
    }

    // Section headers
    let shnum = e.e_shnum as usize;
    let shentsize = e.e_shentsize as usize;
    if shnum > 0 {
        let start = e.e_shoff as usize;
        for j in 0..shnum {
            let b = start + j * shentsize;
            e.shdrs.push(Shdr {
                sh_name: rd_u32(data, b, le),
                sh_type: rd_u32(data, b + 4, le),
                sh_flags: rd_addr(data, b + 8, is64, le),
                sh_addr: rd_addr(data, b + 16, is64, le),
                sh_offset: rd_addr(data, b + 24, is64, le),
                sh_size: rd_addr(data, b + 32, is64, le),
                sh_link: rd_u32(data, b + 40, le),
                sh_info: rd_u32(data, b + 44, le),
                sh_addralign: rd_addr(data, b + 48, is64, le),
                sh_entsize: rd_addr(data, b + 56, is64, le),
            });
        }
    }

    Ok(e)
}

/// Size of the section contents in the file (NOBITS sections occupy no bytes).
pub fn sec_file_size(s: &Shdr) -> u64 {
    if s.sh_type == SHT_NOBITS {
        0
    } else {
        s.sh_size
    }
}

fn len_of(d: &[u8]) -> usize {
    d.len()
}
RSEOF
