// HTML report generation.

use crate::elf::{
    abi_name, machine_name, objtype_name, ptype_name, sec_file_size, sec_flags_str, seg_flags_str,
    shtype_name, Elf, SHT_STRTAB, PT_INTERP, PT_NOTE,
};
use crate::panic;

const HEAD: &str = include_str!("../template/head.txt");
const JS123: &str = include_str!("../template/js123.txt");
const JS4A: &str = include_str!("../template/js4a.txt");
const JS4B: &str = include_str!("../template/js4b.txt");
const JS5A: &str = include_str!("../template/js5a.txt");
const JS6B: &str = include_str!("../template/js6b.txt");

const UNITS: [&str; 6] = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];

/// 1024-based human readable size with one fractional digit.
pub fn human(v: u64) -> String {
    let mut val = v as f64;
    let mut k = 0usize;
    while val >= 1024.0 && k < UNITS.len() {
        val /= 1024.0;
        k += 1;
    }
    format!("{:.1} {}", val, UNITS[k - 1])
}

fn size_str(v: u64) -> String {
    if v < 1024 {
        v.to_string()
    } else {
        format!("{} ({})", v, human(v))
    }
}

fn file_size_str(v: usize) -> String {
    if v < 1024 {
        format!("{} B", v)
    } else {
        format!("{} ({} B)", human(v as u64), v)
    }
}

/// value shown as hex, title holds the decimal form
fn n_hex(v: u64) -> String {
    format!("<span class='number' title='{}'>0x{:x}</span>", v, v)
}

/// value shown as decimal, title holds the hex form
fn n_dec(v: u64) -> String {
    format!("<span class='number' title='0x{:x}'>{}</span>", v, v)
}

/// value shown as decimal with a human readable hint, title holds the hex form
fn n_dec_sz(v: u64) -> String {
    format!("<span class='number' title='0x{:x}'>{}</span>", v, size_str(v))
}

/// Render a byte slice: printable characters verbatim, everything else as
/// bold hexadecimal with a trailing space.
fn render_printable(d: &[u8]) -> String {
    let mut s = String::new();
    for b in d {
        if *b >= 0x21 && *b <= 0x7e {
            s.push(*b as char);
        } else {
            s.push_str(&format!("<b>{:02x}</b> ", b));
        }
    }
    s
}

/// Same as `render_printable` but drops the final byte (assumed to be a
/// terminator).
fn render_printable_trim(d: &[u8]) -> String {
    if d.is_empty() {
        return String::new();
    }
    render_printable(&d[..d.len() - 1])
}

/// Escape text for the ASCII column.
fn esc_ascii(b: u8) -> String {
    match b {
        b'<' => "&lt;".to_string(),
        b'>' => "&gt;".to_string(),
        b'&' => "&amp;".to_string(),
        b'"' => "&quot;".to_string(),
        b'\'' => "&apos;".to_string(),
        c => (c as char).to_string(),
    }
}

fn file_stem(p: &str) -> String {
    match p.rsplit('/').next() {
        Some(s) if !s.is_empty() => s.to_string(),
        _ => p.to_string(),
    }
}

struct Ent {
    start: usize,
    end: usize,
    class: String,
}

struct Note {
    name: String,
    ntype: u32,
    desc: String,
    start: usize,
    end: usize,
}

/// One hexadecimal dump token (two lowercase digits), the ELF magic is shown
/// with its printable characters.
fn token(data: &[u8], off: usize) -> String {
    let b = data[off];
    if off < 4 {
        if b >= 0x21 && b <= 0x7e {
            return format!("&nbsp;{}", b as char);
        }
    }
    format!("{:02x}", b)
}

pub fn generate(data: &[u8], e: &elf::Elf, input: &str) -> String {
    let mut out = String::with_capacity(data.len() * 4 + 1 << 16);
    out.push_str(&HEAD.replace("{TITLE}", &file_stem(input)));
    gen_fileinfo(&mut out, data, e, input);
    out.push_str("    </table>\n");
    gen_offsets(&mut out, data.len());
    let ents = build_ents(data, e);
    gen_bytes(&mut out, data, &ents);
    gen_ascii(&mut out, data);
    gen_info(&mut out, data, e);
    out.push_str(JS123);
    out.push_str(JS4A);
    out.push_str(&format!("      let fileLen = {}\n", data.len()));
    out.push_str(JS4B);
    out.push_str(JS5A);
    gen_connect(&mut out, e);
    out.push_str(JS6B);
    out
}

fn gen_fileinfo(out: &mut String, data: &[u8], e: &Elf, input: &str) {
    out.push_str(&format!(
        "      <tr class='fileinfo_file_name'> <td>File name:</td> <td>{}</td> </tr>\n",
        input
    ));
    out.push_str(&format!(
        "      <tr class='fileinfo_file_size'> <td>File size:</td> <td>{}</td> </tr>\n",
        file_size_str(data.len())
    ));
    out.push_str(&format!(
        "      <tr class='fileinfo_class'> <td>Object class:</td> <td>{}</td> </tr>\n",
        if e.is64 { "64-bit" } else { "32-bit" }
    ));
    out.push_str(&format!(
        "      <tr class='fileinfo_data'> <td>Data encoding:</td> <td>{}</td> </tr>\n",
        if e.le { "Little endian" } else { "Big endian" }
    ));
    out.push_str(&format!(
        "      <tr class='fileinfo_abi'> <td>ABI:</td> <td>{}</td> </tr>\n",
        abi_name(e.abi)
    ));
    out.push_str(&format!(
        "      <tr class='fileinfo_e_type'> <td>Type:</td> <td>{}</td> </tr>\n",
        objtype_name(e.e_type)
    ));
    out.push_str(&format!(
        "      <tr class='fileinfo_e_machine'> <td>Architecture:</td> <td>{}</td> </tr>\n",
        machine_name(e.e_machine)
    ));
    out.push_str(&format!(
        "      <tr class='fileinfo_e_entry'> <td>Entrypoint:</td> <td>{}</td> </tr>\n",
        n_hex(e.e_entry)
    ));
    out.push_str(&format!(
        "      <tr class='fileinfo_ph'> <td>Program headers:</td> <td><span title='0x{:x}' class='number fileinfo_e_phnum'>{}</span> * <span title='0x{:x}' class='number fileinfo_e_phentsize'>{}</span> @ <span title='0x{:x}' class='number fileinfo_e_phoff'>{}</span></td> </tr>\n",
        e.e_phnum, e.e_phnum, e.e_phentsize, e.e_phentsize, e.e_phoff, e.e_phoff
    ));
    out.push_str(&format!(
        "      <tr class='fileinfo_sh'> <td>Section headers:</td> <td><span title='0x{:x}' class='number fileinfo_e_shnum'>{}</span> * <span title='0x{:x}' class='number fileinfo_e_shentsize'>{}</span> @ <span title='0x{:x}' class='number fileinfo_e_shoff'>{}</span></td> </tr>\n",
        e.e_shnum, e.e_shnum, e.e_shentsize, e.e_shentsize, e.e_shoff, e.e_shoff
    ));
}

fn gen_offsets(out: &mut String, len: usize) {
    out.push_str("    <div id='offsets'>");
    let rows = len.div_ceil(16);
    for i in 0..rows {
        if i > 0 {
            out.push('\n');
        }
        out.push_str(&format!("{:x}", i * 16));
    }
    out.push_str("</div>\n");
}

/// Byte position offsets of every ELF field / section / segment highlight.
fn build_ents(data: &[u8], e: &elf::Elf) -> Vec<Ent> {
    let mut ents: Vec<Ent> = Vec::new();
    let mut add = |s: usize, e_: usize, c: &str| ents.push(Ent { start: s, end: e_, class: c.to_string() });

    let ehsize = e.e_ehsize as usize;
    add(0, ehsize, "ehdr");
    add(0, 16, "ident");
    add(0, 4, "magic");
    add(4, 5, "class");
    add(5, 6, "data");
    add(6, 7, "ver");
    add(7, 8, "abi");
    add(8, 9, "abi_ver");
    add(9, 16, "pad");

    let entry_sz = if e.is64 { 8 } else { 4 };
    let mut off = 16;
    for (name, sz) in [
        ("e_type", 2usize),
        ("e_machine", 2),
        ("e_version", 4),
        ("e_entry", entry_sz),
        ("e_phoff", entry_sz),
        ("e_shoff", entry_sz),
        ("e_flags", 4),
        ("e_ehsize", 2),
        ("e_phentsize", 2),
        ("e_phnum", 2),
        ("e_shentsize", 2),
        ("e_shnum", 2),
        ("e_shstrndx", 2),
    ] {
        add(off, off + sz, name);
        off += sz;
    }

    // segments
    let mut notes: Vec<Vec<Note>> = vec![Vec::new(); e.phdrs.len()];
    for (i, p) in e.phdrs.iter().enumerate() {
        if p.p_offset == 0 || p.p_filesz == 0 {
            continue;
        }
        let s = p.p_offset as usize;
        let epos = s + p.p_filesz as usize;
        if epos > data.len() {
            panic::panic_index(data.len(), epos - 1, "src/elf/elfxx.rs:180:9");
        }
        add(s, epos, &format!("bin_segment{} segment", i));
    }

    // program headers and their fields
    for (i, p) in e.phdrs.iter().enumerate() {
        let b = e.e_phoff as usize + i * e.e_phentsize as usize;
        add(b, b + e.e_phentsize as usize, &format!("bin_phdr{} phdr", i));
        let mut off = b;
        for name in [
            "p_type", "p_flags", "p_offset", "p_vaddr", "p_paddr", "p_filesz", "p_memsz", "p_align",
        ] {
            let sz = if name == "p_type" || name == "p_flags" {
                4
            } else if e.is64 {
                8
            } else {
                4
            };
            add(off, off + sz, name);
            off += sz;
        }
    }

    // section headers and their fields
    for (j, s) in e.shdrs.iter().enumerate() {
        let b = e.e_shoff as usize + j * e.e_shentsize as usize;
        add(b, b + e.e_shentsize as usize, &format!("bin_shdr{} shdr", j));
        let mut off = b;
        for name in [
            "sh_name",
            "sh_type",
            "sh_flags",
            "sh_addr",
            "sh_offset",
            "sh_size",
            "sh_link",
            "sh_info",
            "sh_addralign",
            "sh_entsize",
        ] {
            let sz = match name {
                "sh_name" | "sh_type" | "sh_link" | "sh_info" => 4,
                _ => {
                    if e.is64 {
                        8
                    } else {
                        4
                    }
                }
            };
            add(off, off + sz, name);
            off += sz;
        }
    }

    // sections
    for (j, s) in e.shdrs.iter().enumerate() {
        let fsz = sec_file_size(s) as usize;
        if fsz == 0 {
            continue;
        }
        let st = s.sh_offset as usize;
        if st + fsz > data.len() {
            panic::panic_index(data.len(), st + fsz - 1, "src/elf/parser.rs:170:9");
        }
        add(st, st + fsz, &format!("bin_section{} section hover", j));
    }

    // note entries inside NOTE segments
    for (i, p) in e.phdrs.iter().enumerate() {
        if p.p_offset == 0 || p.p_filesz == 0 || p.p_type != PT_NOTE {
            continue;
        }
        let s = p.p_offset as usize;
        let epos = s + p.p_filesz as usize;
        notes[i] = parse_notes(data, s, epos);
        for n in &notes[i] {
            add(n.start, n.end, "segment_subrange hover");
        }
    }
    let _ = &mut notes;
    ents
}

/// Parse the note entries of a NOTE segment.
fn parse_notes(data: &[u8], start: usize, end: usize) -> Vec<Note> {
    let mut res: Vec<Note> = Vec::new();
    let mut off = start;
    while off < end {
        let rem = end - off;
        if rem < 12 {
            if rem < 4 {
                panic::panic_range(4, rem, "src/elf/elfxx.rs:200:30");
            } else if rem < 8 {
                panic::panic_range(8, rem, "src/elf/elfxx.rs:200:30");
            } else {
                panic::panic_range(12, rem, "src/elf/elfxx.rs:200:30");
            }
        }
        let rd32 = |o: usize| -> u32 {
            u32::from_le_bytes([data[o], data[o + 1], data[o + 2], data[o + 3]])
        };
        let rd32be = |o: usize| -> u32 {
            u32::from_be_bytes([data[o], data[o + 1], data[o + 2], data[o + 3]])
        };
        let rd = if crate::render::current_le { rd32 } else { rd32be };
        let namesz = rd(off) as usize;
        let descsz = rd(off + 4) as usize;
        let ntype = rd(off + 8);
        let need = 12 + pad4(namesz as u64) + pad4(descsz as u64);
        if need as usize > rem {
            break;
        }
        let name_off = off + 12;
        let name = render_printable_trim(&data[name_off..name_off + namesz]);
        let desc_off = off + 12 + namesz;
        let desc = render_printable(&data[desc_off..desc_off + descsz]);
        res.push(Note {
            name,
            ntype,
            desc,
            start: off,
            end: off + need as usize,
        });
        off += need as usize;
    }
    res
}

fn pad4(v: u64) -> u64 {
    (v + 3) & !3
}

/// Emit raw dump text for data[pos..end] honouring the 16 byte rows.
fn emit_text(out: &mut String, data: &[u8], pos: usize, end: usize) {
    for o in pos..end {
        if o != 0 {
            out.push_str(if o % 16 == 0 { "\n" } else { " " });
        }
        out.push_str(&token(data, o));
    }
}

fn gen_bytes(out: &mut String, data: &[u8], ents: &[Ent]) {
    out.push_str("    <div id='bytes'>");
    let mut evs: Vec<(usize, u8, usize)> = Vec::with_capacity(ents.len() * 2);
    for (i, e_) in ents.iter().enumerate() {
        evs.push((e_.start, 1, i));
        evs.push((e_.end, 0, i));
    }
    evs.sort_by_key(|&(o, k, i)| (o, k, i));
    let mut pos = 0usize;
    for &(o, k, i) in &evs {
        emit_text(out, data, pos, o);
        if k == 1 {
            out.push_str(&format!("<span class='{}'>", ents[i].class));
        } else {
            out.push_str("</span>");
        }
        pos = o;
    }
    emit_text(out, data, pos, data.len());
    out.push_str("</div>\n");
}

fn gen_ascii(out: &mut String, data: &[u8]) {
    out.push_str("    <div id='ascii'>");
    let rows = data.len().div_ceil(16);
    for r in 0..rows {
        if r > 0 {
            out.push('\n');
        }
        let st = r * 16;
        let en = (st + 16).min(data.len());
        for b in &data[st..en] {
            if *b >= 0x21 && *b <= 0x7e {
                out.push_str(&esc_ascii(*b));
            } else {
                out.push('.');
            }
        }
    }
    out.push_str("</div>\n");
}

fn gen_info(out: &mut String, data: &[u8], e: &Elf) {
    out.push_str("    <table id='sticky_table' cellspacing='0'>\n");
    out.push_str("      <tr>\n");
    out.push_str("        <td id='desc'></td>\n");
    out.push_str("        <td class='infotables'>\n");
    for (i, p) in e.phdrs.iter().enumerate() {
        out.push_str(&format!(
            "          <table class='conceal itable' id='info_phdr{}'>\n",
            i
        ));
        out.push_str("          <th colspan='2' class='phdr_itable'></th>\n");
        out.push_str(&format!("            <tr> <td>Type:</td> <td>{}</td> </tr>\n", ptype_name(p.p_type)));
        out.push_str(&format!(
            "            <tr> <td>Flags:</td> <td>{}</td> </tr>\n",
            seg_flags_str(p.p_flags)
        ));
        out.push_str(&format!("            <tr> <td>Offset in file:</td> <td>{}</td> </tr>\n", n_hex(p.p_offset)));
        out.push_str(&format!("            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n", n_dec_sz(p.p_filesz)));
        out.push_str(&format!("            <tr> <td>Vaddr in memory:</td> <td>{}</td> </tr>\n", n_hex(p.p_vaddr)));
        out.push_str(&format!("            <tr> <td>Size in memory:</td> <td>{}</td> </tr>\n", n_dec_sz(p.p_memsz)));
        out.push_str(&format!("            <tr> <td>Alignment:</td> <td>{}</td> </tr>\n", n_hex(p.p_align)));
        let rendered = p.p_offset != 0 && p.p_filesz != 0;
        if rendered && p.p_type == PT_INTERP {
            out.push_str("            <tr><td><br></td></tr>\n");
            let s = p.p_offset as usize;
            let en = s + p.p_filesz as usize;
            let interp = render_printable_trim(&data[s..en - 1]);
            out.push_str(&format!(
                "            <tr> <td>Interpreter:</td> <td>{}</td> </tr>\n",
                interp
            ));
        } else if rendered && p.p_type == PT_NOTE {
            let s = p.p_offset as usize;
            let en = s + p.p_filesz as usize;
            let notes = parse_notes(data, s, en);
            out.push_str("            <tr><td><br></td></tr>\n");
            for (k, n) in notes.iter().enumerate() {
                if k > 0 {
                    out.push_str("            <tr> <td><br></td> </tr>\n");
                }
                out.push_str(&format!("            <tr> <td>Name:</td> <td>{}</td> </tr>\n", n.name));
                out.push_str(&format!("            <tr> <td>Type:</td> <td>0x{:x}</td> </tr>\n", n.ntype));
                if n.ntype == 3 {
                    out.push_str(&format!("            <tr> <td>Build ID:</td> <td>{}</td> </tr>\n", hex_str(&data[0..0])));
                } else {
                    out.push_str(&format!("            <tr> <td>Desc:</td> <td>{}</td> </tr>\n", n.desc));
                }
            }
        }
        out.push_str("          </table>\n");
    }
    for (j, s) in e.shdrs.iter().enumerate() {
        out.push_str(&format!(
            "          <table class='conceal itable' id='info_shdr{}'>\n",
            j
        ));
        out.push_str("          <th colspan='2' class='shdr_itable'></th>\n");
        out.push_str(&format!("            <tr> <td>Index:</td> <td>{}</td> </tr>\n", j));
        let name = sec_name(data, e, s.sh_name as usize);
        out.push_str(&format!("            <tr> <td>Name:</td> <td>{}</td> </tr>\n", name));
        out.push_str(&format!("            <tr> <td>Type:</td> <td>{}</td> </tr>\n", shtype_name(s.sh_type)));
        out.push_str(&format!("            <tr> <td>Flags:</td> <td>{}</td> </tr>\n", sec_flags_str(s.sh_flags)));
        out.push_str(&format!("            <tr> <td>Vaddr in memory:</td> <td>{}</td> </tr>\n", n_hex(s.sh_addr)));
        out.push_str(&format!("            <tr> <td>Offset in file:</td> <td>{}</td> </tr>\n", n_hex(s.sh_offset)));
        out.push_str(&format!("            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n", n_dec_sz(s.sh_size)));
        out.push_str(&format!("            <tr> <td>Linked section:</td> <td>{}</td> </tr>\n", s.sh_link));
        out.push_str(&format!("            <tr> <td>Extra info:</td> <td>{}</td> </tr>\n", n_dec(s.sh_info as u64)));
        out.push_str(&format!("            <tr> <td>Alignment:</td> <td>{}</td> </tr>\n", n_hex(s.sh_addralign)));
        out.push_str(&format!("            <tr> <td>Size of entries:</td> <td>{}</td> </tr>\n", n_dec_sz(s.sh_entsize)));
        out.push_str("          </table>\n");
    }
    out.push_str("        </td>\n");
    out.push_str("        <td class='infotables'>\n");
    for (i, p) in e.phdrs.iter().enumerate() {
        out.push_str(&format!(
            "          <table class='conceal itable' id='info_segment{}'>\n",
            i
