    }
    for (j, s) in e.shdrs.iter().enumerate() {
        out.push_str(&format!(
            "          <table class='conceal itable' id='info_section{}'>\n",
            j
        ));
        out.push_str("          <th colspan='2' class='section_itable'></th>\n");
        out.push_str(&format!("            <tr> <td>Type:</td> <td>{}</td> </tr>\n", shtype_name(s.sh_type)));
        out.push_str(&format!("            <tr> <td>Size:</td> <td>{}</td> </tr>\n", n_dec_sz(s.sh_size)));
        if s.sh_type == SHT_STRTAB {
            out.push_str("            <tr><td><br></td></tr>\n");
            out.push_str("            <tr>\n");
            out.push_str("              <td></td>\n");
            out.push_str("              <td>\n");
            out.push_str("                <div>\n");
            for st in strtab_strings(data, s) {
                out.push_str(&format!("                  {}\n", st));
            }
            out.push_str("                </div>\n");
            out.push_str("              </td>\n");
            out.push_str("            </tr>\n");
        }
        out.push_str("          </table>\n");
    }
    out.push_str("        </td>\n");
    out.push_str("      </tr>\n");
    out.push_str("    </table>\n");
}

fn hex_str(d: &[u8]) -> String {
    d.iter().map(|b| format!("{:02x}", b)).collect::<String>()
}

/// Section name looked up in the string table.
fn sec_name(data: &[u8], e: &Elf, off: usize) -> String {
    if e.e_shstrndx == 0 || e.shdrs.is_empty() {
        return String::new();
    }
    if (e.e_shstrndx as usize) >= e.shdrs.len() {
        return String::new();
    }
    let st = e.shdrs[e.e_shstrndx as usize].sh_offset as usize;
    let sz = e.shdrs[e.e_shstrndx as usize].sh_size as usize;
    if off >= sz {
        return String::new();
    }
    let base = st + off;
    let mut en = base;
    while en < st + sz && en < data.len() && data[en] != 0 {
        en += 1;
    }
    String::from_utf8_lossy(&data[base..en]).into_owned()
}

/// List of strings contained in a STRTAB section.
fn strtab_strings(data: &[u8], s: &elf::Shdr) -> Vec<String> {
    let st = s.sh_offset as usize;
    let sz = s.sh_size as usize;
    if st > data.len() || st + sz > data.len() {
        panic::panic_index(data.len(), st + sz - 1, "src/elf/parser.rs:170:9");
    }
    let seg = &data[st..st + sz];
    let mut res: Vec<String> = Vec::new();
    let mut start = 0usize;
    for (i, b) in seg.iter().enumerate() {
        if *b != 0 {
            continue;
        }
        let sl = &seg[start..i];
        if sl.is_empty() {
            start = i + 1;
            continue;
        }
        let bytes = if start == 0 { &sl[..1] } else { sl };
        if let Ok(v) = std::str::from_utf8(bytes) {
            res.push(v.to_string());
        }
        start = i + 1;
    }
    res
}

fn gen_connect(out: &mut String, e: &Elf) {
    out.push_str("      connect('.e_phoff', '.bin_phdr0');\n");
    out.push_str("      connect('.e_shoff', '.bin_shdr0');\n");
    for i in 0..e.phdrs.len() {
        out.push_str(&format!(
            "      connect('.bin_phdr{} > .p_offset', '.bin_segment{}');\n",
            i, i
        ));
    }
    for (j, s) in e.shdrs.iter().enumerate() {
        out.push_str(&format!(
            "      connect('.bin_shdr{} > .sh_offset', '.bin_section{}');\n",
            j, j
        ));
        if s.sh_link != 0 {
            out.push_str(&format!(
                "      connect('.bin_shdr{} > .sh_link', '.bin_shdr{}');\n",
                j, s.sh_link
            ));
        }
    }
}
