        }
        out.push_str(&format!("{:x}", i * 16));
    }
    out.push_str("</div>\n");
}

/// Byte ranges of every ELF field / section / segment highlight.
fn build_ents(data: &[u8], e: &Elf) -> Vec<Ent> {
    let mut ents: Vec<Ent> = Vec::new();
    let mut add = |s: usize, e_: usize, c: &str| {
        ents.push(Ent {
            start: s,
            end: e_,
            class: c.to_string(),
        })
    };

    let ehsize = e.e_ehsize as usize;
    add(0, ehsize, "ehdr");
    add(0, 16, "ident");
    add(0, 4, "magic");
    add(4, 5, "class");
    add(5, 6, "data");
    add(6, 7, "ver");
    add(7, 8, "abi");
    add(8, 9, "abi_ver");
    add(9, 16, "pad");

    let entry_sz = if e.is64 { 8 } else { 4 };
    let mut off = 16;
    for (name, sz) in [
        ("e_type", 2usize),
        ("e_machine", 2),
        ("e_version", 4),
        ("e_entry", entry_sz),
        ("e_phoff", entry_sz),
        ("e_shoff", entry_sz),
        ("e_flags", 4),
        ("e_ehsize", 2),
        ("e_phentsize", 2),
        ("e_phnum", 2),
        ("e_shentsize", 2),
        ("e_shnum", 2),
        ("e_shstrndx", 2),
    ] {
        add(off, off + sz, name);
        off += sz;
    }

    // segments
    for (i, p) in e.phdrs.iter().enumerate() {
        if p.p_offset == 0 || p.p_filesz == 0 {
            continue;
        }
        let s = p.p_offset as usize;
        let epos = s + p.p_filesz as usize;
        if epos > data.len() {
            panic::panic_index(data.len(), epos - 1, "src/elf/elfxx.rs:180:9");
        }
        add(s, epos, &format!("bin_segment{} segment", i));
    }

    // program headers and their fields
    for (i, _p) in e.phdrs.iter().enumerate() {
        let b = e.e_phoff as usize + i * e.e_phentsize as usize;
        add(b, b + e.e_phentsize as usize, &format!("bin_phdr{} phdr", i));
        let mut off = b;
        for name in [
            "p_type", "p_flags", "p_offset", "p_vaddr", "p_paddr", "p_filesz", "p_memsz", "p_align",
        ] {
            let sz = match name {
                "p_type" | "p_flags" => 4,
                _ => {
                    if e.is64 {
                        8
                    } else {
                        4
                    }
                }
            };
            add(off, off + sz, name);
            off += sz;
        }
    }

    // section headers and their fields
    for (j, _s) in e.shdrs.iter().enumerate() {
        let b = e.e_shoff as usize + j * e.e_shentsize as usize;
        add(b, b + e.e_shentsize as usize, &format!("bin_shdr{} shdr", j));
        let mut off = b;
        for name in [
            "sh_name",
            "sh_type",
            "sh_flags",
            "sh_addr",
            "sh_offset",
            "sh_size",
            "sh_link",
            "sh_info",
            "sh_addralign",
            "sh_entsize",
        ] {
            let sz = match name {
                "sh_name" | "sh_type" | "sh_link" | "sh_info" => 4,
                _ => {
                    if e.is64 {
                        8
                    } else {
                        4
                    }
                }
            };
            add(off, off + sz, name);
            off += sz;
        }
    }

    // sections
    for (j, s) in e.shdrs.iter().enumerate() {
        let fsz = sec_file_size(s) as usize;
        if fsz == 0 {
            continue;
        }
        let st = s.sh_offset as usize;
        if st + fsz > data.len() {
            panic::panic_index(data.len(), st + fsz - 1, "src/elf/parser.rs:170:9");
        }
        add(st, st + fsz, &format!("bin_section{} section hover", j));
    }

    // note entries inside NOTE segments
    for (i, p) in e.phdrs.iter().enumerate() {
        if p.p_offset == 0 || p.p_filesz == 0 || p.p_type != PT_NOTE {
            continue;
        }
        let s = p.p_offset as usize;
        let epos = s + p.p_filesz as usize;
        for n in parse_notes(data, e, s, epos) {
            add(n.start, n.end, "segment_subrange hover");
        }
    }
    ents
}

fn pad4(v: u64) -> u64 {
    (v + 3) & !3
}

/// Parse the note entries of a NOTE segment.
fn parse_notes(data: &[u8], e: &Elf, start: usize, end: usize) -> Vec<Note> {
    let mut res: Vec<Note> = Vec::new();
    let mut off = start;
    while off < end {
        let rem = end - off;
        if rem < 12 {
            let loc = "src/elf/elfxx.rs:212:34";
            if rem < 4 {
                panic::panic_range(4, rem, loc);
            } else if rem < 8 {
                panic::panic_range(8, rem, loc);
            } else {
                panic::panic_range(12, rem, loc);
            }
        }
        let namesz = crate::elf::rd_u32(data, off, e.le) as usize;
        let descsz = crate::elf::rd_u32(data, off + 4, e.le) as usize;
        let ntype = crate::elf::rd_u32(data, off + 8, e.le);
        let need = (12 + pad4(namesz as u64) + pad4(descsz as u64)) as usize;
        if need > rem {
            break;
        }
        let name_off = off + 12;
        let name = render_printable_trim(&data[name_off..name_off + namesz]);
        let desc_off = off + 12 + namesz;
        let desc_raw = data[desc_off..desc_off + descsz].to_vec();
        let desc = render_printable(&desc_raw);
        res.push(Note {
            name,
            ntype,
            desc,
            desc_raw,
            start: off,
            end: off + need,
        });
        off += need;
    }
    res
}

/// Emit raw dump text for data[pos..end] honouring the 16 byte rows.
fn emit_text(out: &mut String, data: &[u8], pos: usize, end: usize) {
    for o in pos..end {
        if o != 0 {
            out.push_str(if o % 16 == 0 { "\n" } else { " " });
        }
        out.push_str(&token(data, o));
    }
}

fn gen_bytes(out: &mut String, data: &[u8], ents: &[Ent]) {
    out.push_str("    <div id='bytes'>");
    let mut evs: Vec<(usize, u8, usize)> = Vec::with_capacity(ents.len() * 2);
    for (i, e_) in ents.iter().enumerate() {
        evs.push((e_.start, 1, i));
        evs.push((e_.end, 0, i));
    }
    evs.sort_by_key(|&(o, k, i)| (o, k, i));
    let mut pos = 0usize;
    for &(o, k, i) in &evs {
        emit_text(out, data, pos, o);
        if k == 1 {
            out.push_str(&format!("<span class='{}'>", ents[i].class));
        } else {
            out.push_str("</span>");
        }
        pos = o;
    }
    emit_text(out, data, pos, data.len());
    out.push_str("</div>\n");
}

fn gen_ascii(out: &mut String, data: &[u8]) {
    out.push_str("    <div id='ascii'>");
    let rows = data.len().div_ceil(16);
    for r in 0..rows {
        if r > 0 {
            out.push('\n');
        }
        let st = r * 16;
        let en = (st + 16).min(data.len());
        for b in &data[st..en] {
            if *b >= 0x21 && *b <= 0x7e {
                out.push_str(&esc_ascii(*b));
            } else {
                out.push('.');
            }
        }
    }
    out.push_str("</div>\n");
}

fn gen_info(out: &mut String, data: &[u8], e: &Elf) {
    out.push_str("    <table id='sticky_table' cellspacing='0'>\n");
    out.push_str("      <tr>\n");
    out.push_str("        <td id='desc'></td>\n");
    out.push_str("        <td class='infotables'>\n");
    for (i, p) in e.phdrs.iter().enumerate() {
        phdr_table(out, data, e, i);
    }
    for (j, s) in e.shdrs.iter().enumerate() {
        out.push_str(&format!(
            "          <table class='conceal itable' id='info_shdr{}'>\n",
            j
        ));
        out.push_str("          <th colspan='2' class='shdr_itable'></th>\n");
        out.push_str(&format!(
            "            <tr> <td>Index:</td> <td>{}</td> </tr>\n",
            j
        ));
        let name = sec_name(data, e, s.sh_name as usize);
        out.push_str(&format!(
            "            <tr> <td>Name:</td> <td>{}</td> </tr>\n",
            name
        ));
        out.push_str(&format!(
            "            <tr> <td>Type:</td> <td>{}</td> </tr>\n",
            shtype_name(s.sh_type)
        ));
        out.push_str(&format!(
            "            <tr> <td>Flags:</td> <td>{}</td> </tr>\n",
            sec_flags_str(s.sh_flags)
        ));
        out.push_str(&format!(
            "            <tr> <td>Vaddr in memory:</td> <td>{}</td> </tr>\n",
            n_hex(s.sh_addr)
        ));
        out.push_str(&format!(
            "            <tr> <td>Offset in file:</td> <td>{}</td> </tr>\n",
            n_hex(s.sh_offset)
        ));
        out.push_str(&format!(
            "            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n",
            n_dec_sz(s.sh_size)
        ));
        out.push_str(&format!(
            "            <tr> <td>Linked section:</td> <td>{}</td> </tr>\n",
            s.sh_link
        ));
        out.push_str(&format!(
            "            <tr> <td>Extra info:</td> <td>{}</td> </tr>\n",
            n_dec(s.sh_info as u64)
        ));
        out.push_str(&format!(
            "            <tr> <td>Alignment:</td> <td>{}</td> </tr>\n",
            n_hex(s.sh_addralign)
        ));
        out.push_str(&format!(
            "            <tr> <td>Size of entries:</td> <td>{}</td> </tr>\n",
            n_dec_sz(s.sh_entsize)
        ));
        out.push_str("          </table>\n");
    }
    out.push_str("        </td>\n");
    out.push_str("        <td class='infotables'>\n");
    for (i, _p) in e.phdrs.iter().enumerate() {
        out.push_str(&format!(
            "          <table class='conceal itable' id='info_segment{}'>\n",
            i
        ));
        out.push_str("          <th colspan='2' class='segment_itable'></th>\n");
        out.push_str(&format!(
            "            <tr> <td>Type:</td> <td>{}</td> </tr>\n",
            ptype_name(e.phdrs[i].p_type)
        ));
        out.push_str(&format!(
            "            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n",
            n_dec_sz(e.phdrs[i].p_filesz)
        ));
        out.push_str(&format!(
            "            <tr> <td>Size in memory:</td> <td>{}</td> </tr>\n",
            n_dec_sz(e.phdrs[i].p_memsz)
        ));
        gen_segment_extra(out, data, e, i);
        out.push_str("          </table>\n");
    }
    for (j, s) in e.shdrs.iter().enumerate() {
        out.push_str(&format!(
            "          <table class='conceal itable' id='info_section{}'>\n",
            j
        ));
        out.push_str("          <th colspan='2' class='section_itable'></th>\n");
        out.push_str(&format!(
            "            <tr> <td>Type:</td> <td>{}</td> </tr>\n",
