        ));
        out.push_str(&format!(
            "            <tr> <td>Size:</td> <td>{}</td> </tr>\n",
            n_dec_sz(s.sh_size)
        ));
        if s.sh_type == SHT_STRTAB {
            out.push_str("            <tr><td><br></td></tr>\n");
            out.push_str("            <tr>\n");
            out.push_str("              <td></td>\n");
            out.push_str("              <td>\n");
            out.push_str("                <div>\n");
            for st in strtab_strings(data, s) {
                out.push_str(&format!("                  {}\n", st));
            }
            out.push_str("                </div>\n");
            out.push_str("              </td>\n");
            out.push_str("            </tr>\n");
        }
        out.push_str("          </table>\n");
    }
    out.push_str("        </td>\n");
    out.push_str("      </tr>\n");
    out.push_str("    </table>\n");
}

/// Interpreter / note rows of a segment info table.
fn gen_segment_extra(out: &mut String, data: &[u8], e: &Elf, i: usize) {
    let p = &e.phdrs[i];
    if p.p_offset == 0 || p.p_filesz == 0 {
        return;
    }
    let s = p.p_offset as usize;
    let en = s + p.p_filesz as usize;
    if p.p_type == PT_INTERP {
        out.push_str("            <tr><td><br></td></tr>\n");
        let interp = render_printable_trim(&data[s..en - 1]);
        out.push_str(&format!(
            "            <tr> <td>Interpreter:</td> <td>{}</td> </tr>\n",
            interp
        ));
    } else if p.p_type == PT_NOTE {
        out.push_str("            <tr><td><br></td></tr>\n");
        for (k, n) in parse_notes(data, e, s, en).iter().enumerate() {
            if k > 0 {
                out.push_str("            <tr> <td><br></td> </tr>\n");
            }
            out.push_str(&format!(
                "            <tr> <td>Name:</td> <td>{}</td> </tr>\n",
                n.name
            ));
            out.push_str(&format!(
                "            <tr> <td>Type:</td> <td>0x{:x}</td> </tr>\n",
                n.ntype
            ));
            if n.ntype == 3 {
                out.push_str(&format!(
                    "            <tr> <td>Build ID:</td> <td>{}</td> </tr>\n",
                    hex_str(&n.desc_raw)
                ));
            } else {
                out.push_str(&format!(
                    "            <tr> <td>Desc:</td> <td>{}</td> </tr>\n",
                    n.desc
                ));
            }
        }
    }
}

