/// A closing tag never gets one, and neither does an element that directly
/// follows the opening tag of its parent.
fn sep_for(prev: Option<(usize, u8)>, o: usize) -> &'static str {
    if let Some((po, pk)) = prev {
        if pk == 1 && po == o {
            return "";
        }
    }
    if o == 0 {
        return "";
    }
    if o % 16 == 0 {
        "\\n"
    } else {
        " "
    }
}

/// Emit raw dump text for data[pos..end], updating the "previous element"
/// state used for separator placement.
fn emit_text(out: &mut String, data: &[u8], pos: usize, end: usize, prev: &mut Option<(usize, u8)>) {
    for o in pos..end {
        out.push_str(sep_for(*prev, o));
        out.push_str(&token(data, o));
        *prev = Some((o, 2));
    }
}

fn gen_bytes(out: &mut String, data: &[u8], ents: &[Ent]) {
    out.push_str("    <div id='bytes'>");
    let mut evs: Vec<(usize, u8, usize)> = Vec::with_capacity(ents.len() * 2);
    for (i, e_) in ents.iter().enumerate() {
        evs.push((e_.start, 1, i));
        evs.push((e_.end, 0, i));
    }
    evs.sort_by_key(|&(o, k, i)| (o, k, i));
    let mut pos = 0usize;
    let mut prev: Option<(usize, u8)> = None;
    for &(o, k, i) in &evs {
        emit_text(out, data, pos, o, &mut prev);
        if k == 1 {
            out.push_str(&format!("<span class='{}'>", ents[i].class));
            prev = Some((o, 1));
        } else {
            out.push_str("</span>");
            prev = Some((o, 0));
        }
        pos = o;
    }
    emit_text(out, data, pos, data.len(), &mut prev);
    out.push_str("</div>\\n");
}

'''
