{"command": "cd /tmp/cmp && python3 -c "
d=open('test','rb').read()
s=open('test.html').read()
a1=s.index(\"id='ascii'>\")+len(\"id='ascii'>\"); a2=s.index('</div>',a1)
rows=s[a1:a2].split('\n')
exp=[]
M={'<':'&lt;','>':'&gt;','&':'&amp;','\"':'&quot;',\"'\":'&apos;'}
for r in range((len(d)+15)//16):
    row=d[r*16:(r+1)*16]
    e=''.join((M.get(chr(c),chr(c)) if 0x21<=c<=0x7e else '.') for c in row)
    exp.append(e)
for i in range(min(len(rows),len(exp))):
    if rows[i]!=exp[i]:
        print('diff at',i, repr(rows[i])[:60], repr(exp[i])[:60]); break
else: print('ascii OK')
""}

